#!/usr/bin/env python3
"""Embed project-owned TB01 sections without reading manufacturer firmware."""

import argparse
import hashlib
from pathlib import Path

import build_tb01_patch as builder


def render(llvm_bin=None):
    """Compile pinned TB01 sections and render cumulative reconstruction helpers."""
    sections, _ = builder.compile_patch(llvm_bin)
    offsets = {name: offset for name, (offset, _) in builder.HOOKS.items()}
    offsets["candidate"] = builder.CODE_OFFSET
    lines = [
        "#pragma once",
        "// Generated by tools/embed_tb01_patch.py from project-owned sections.",
        "// The caller must verify exact source and complete output application hashes.",
        '#include "reset_speed_patch.h"',
        "namespace esphome::desk_firmware_update {",
        f'static constexpr const char *TB01_SHA = "{builder.OUTPUT_APP_SHA256}";',
        f"static constexpr size_t TB01_PAYLOAD_SIZE = {builder.PAYLOAD_SIZE};",
    ]
    for name, data in sections.items():
        lines += [
            f"// {name}: SHA-256 {hashlib.sha256(data).hexdigest()}",
            f"static constexpr uint8_t TB01_{name.upper()}[] = {{",
        ]
        for start in range(0, len(data), 16):
            lines.append(
                "  " + ",".join(f"0x{b:02x}" for b in data[start : start + 16]) + ","
            )
        lines.append("};")
    lines += ["inline uint8_t tb01_byte(size_t offset, uint8_t stock) {"]
    for name in sections:
        offset = offsets[name] - builder.APP_OFFSET
        symbol = "TB01_" + name.upper()
        lines.append(
            f"  if (offset >= 0x{offset:x} && offset < 0x{offset:x} + sizeof({symbol})) return {symbol}[offset - 0x{offset:x}];"
        )
    lines += [
        "  return rs01_byte(offset, stock);",
        "}",
        "inline bool apply_tb01(uint8_t *image, size_t size) {",
        "  if (!image || size != IMAGE_SIZE) return false;",
    ]
    for name, (offset, expected) in builder.HOOKS.items():
        symbol = "before_" + name
        values = ",".join(f"0x{b:02x}" for b in expected)
        lines += [
            f"  const uint8_t {symbol}[] = {{{values}}};",
            f"  if (std::memcmp(image + 0x{offset - builder.APP_OFFSET:x}, {symbol}, sizeof({symbol}))) return false;",
        ]
    lines.append(
        f"  for (size_t i = 0x{builder.CODE_OFFSET - builder.APP_OFFSET:x}; i < IMAGE_SIZE; ++i) if (image[i] != 255) return false;"
    )
    for name in sections:
        offset = offsets[name] - builder.APP_OFFSET
        symbol = "TB01_" + name.upper()
        lines.append(
            f"  std::memcpy(image + 0x{offset:x}, {symbol}, sizeof({symbol}));"
        )
    lines += [
        "  return true;",
        "}",
        "// Exact TB01 input and restored R7 output hashes are required at the caller.",
        "inline bool remove_tb01(uint8_t *image, size_t size) {",
        "  if (!image || size != IMAGE_SIZE) return false;",
    ]
    for name in sections:
        offset = offsets[name] - builder.APP_OFFSET
        symbol = "TB01_" + name.upper()
        lines.append(
            f"  if (std::memcmp(image + 0x{offset:x}, {symbol}, sizeof({symbol}))) return false;"
        )
    for name, (offset, expected) in builder.HOOKS.items():
        values = ",".join(f"0x{b:02x}" for b in expected)
        symbol = "before_" + name
        lines += [
            f"  const uint8_t {symbol}[] = {{{values}}};",
            f"  std::memcpy(image + 0x{offset - builder.APP_OFFSET:x}, {symbol}, sizeof({symbol}));",
        ]
    lines += [
        f"  std::memset(image + 0x{builder.CODE_OFFSET - builder.APP_OFFSET:x}, 255, {builder.CODE_CAPACITY});",
        "  return true;",
        "}",
        "}  // namespace esphome::desk_firmware_update",
        "",
    ]
    return "\n".join(lines)


def main():
    """Regenerate the TB01 header or reject stale checked-in output."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--llvm-bin", type=Path)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    output = builder.ROOT / "components/desk_firmware_update/tb01_patch.h"
    expected = render(args.llvm_bin)
    if args.check:
        if not output.is_file() or output.read_text() != expected:
            raise SystemExit("tb01_patch.h is stale: run tools/embed_tb01_patch.py")
    else:
        output.write_text(expected)


if __name__ == "__main__":
    main()
